"use client";

import { useState, useEffect, type ComponentType } from "react";
import { useCart } from "@/context/CartContext";
import { useAuth } from "@/context/AuthContext";
import { formatVND, productImageUrl } from "@/lib/utils";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  buildFullAddress,
  fetchProvinces,
  fetchWards,
  findProvince,
  findWard,
  type ProvinceOption,
  type WardOption,
} from "@/lib/locations";
import { AlertCircle, ArrowLeft, Check, CreditCard, Landmark, QrCode, ShoppingBag, Wallet, X } from "lucide-react";
import Link from "next/link";
import Image from "next/image";

type PaymentMethod = "cod" | "momo" | "vnpay";

type CheckoutAddressBlockProps = {
  address: string;
  provinceCode: string;
  wardCode: string;
  provinces: ProvinceOption[];
  wards: WardOption[];
  required?: boolean;
  detailLabel: string;
  onAddressChange: (value: string) => void;
  onProvinceChange: (value: string) => void;
  onWardChange: (value: string) => void;
};

const paymentOptions: {
  id: PaymentMethod;
  title: string;
  description: string;
  icon: ComponentType<{ className?: string }>;
}[] = [
  {
    id: "cod",
    title: "Thanh toán khi nhận hàng",
    description: "Thanh toán bằng tiền mặt khi đơn hàng được giao tới bạn.",
    icon: Wallet,
  },
  {
    id: "momo",
    title: "Ví MoMo",
    description: "Tạo đơn hàng với phương thức MoMo. Bản demo chưa kết nối cổng thanh toán thật.",
    icon: QrCode,
  },
  {
    id: "vnpay",
    title: "VNPay",
    description: "Thanh toán online qua cổng VNPay bằng thẻ ATM, thẻ quốc tế hoặc mã QR.",
    icon: Landmark,
  },
];

function CheckoutAddressBlock({
  address,
  provinceCode,
  wardCode,
  provinces,
  wards,
  required = true,
  detailLabel,
  onAddressChange,
  onProvinceChange,
  onWardChange,
}: CheckoutAddressBlockProps) {
  return (
    <div className="space-y-3">
      <div className="space-y-2">
        <label className="text-sm font-medium text-[#f7efe1]">{detailLabel}</label>
        <Input
          required={required}
          className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45"
          value={address}
          onChange={(event) => onAddressChange(event.target.value)}
          placeholder="Số nhà, tên đường"
        />
      </div>
      <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <div className="space-y-2">
          <label className="text-sm font-medium text-[#f7efe1]">Tỉnh/Thành phố</label>
          <Select value={provinceCode} onValueChange={onProvinceChange}>
            <SelectTrigger className="h-11 rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1]">
              <SelectValue placeholder="Chọn tỉnh/thành" />
            </SelectTrigger>
            <SelectContent>
              {provinces.map((province) => (
                <SelectItem key={province.code} value={province.code}>
                  {province.full_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <label className="text-sm font-medium text-[#f7efe1]">Phường/Xã</label>
          <Select value={wardCode} onValueChange={onWardChange} disabled={!provinceCode}>
            <SelectTrigger className="h-11 rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1]">
              <SelectValue placeholder={provinceCode ? "Chọn phường/xã" : "Chọn tỉnh trước"} />
            </SelectTrigger>
            <SelectContent>
              {wards.map((ward) => (
                <SelectItem key={ward.code} value={ward.code}>
                  {ward.full_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
    </div>
  );
}

export default function CheckoutPage() {
  const { cart, clearCart } = useCart();
  const { user, token } = useAuth();
  const router = useRouter();

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    province_code: "",
    ward_code: "",
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [orderNumber, setOrderNumber] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod | null>(null);
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [isCartReady, setIsCartReady] = useState(false);

  const [isDifferentRecipient, setIsDifferentRecipient] = useState(false);
  const [recipientData, setRecipientData] = useState({
    name: "",
    phone: "",
    address: "",
    province_code: "",
    ward_code: "",
  });
  const [provinces, setProvinces] = useState<ProvinceOption[]>([]);
  const [customerWards, setCustomerWards] = useState<WardOption[]>([]);
  const [recipientWards, setRecipientWards] = useState<WardOption[]>([]);
  const [locationError, setLocationError] = useState("");

  // Pre-fill user data if logged in
  useEffect(() => {
    if (user) {
      setFormData(prev => ({
        ...prev,
        name: user.name || "",
        email: user.email || "",
        phone: user.phone || "",
        address: user.address_detail || user.address || "",
        province_code: user.province_code || "",
        ward_code: user.ward_code || "",
      }));
    }
  }, [user]);

  useEffect(() => {
    fetchProvinces()
      .then(setProvinces)
      .catch((error) => setLocationError(error instanceof Error ? error.message : "Không thể tải tỉnh/thành."));
  }, []);

  useEffect(() => {
    if (!formData.province_code) {
      setCustomerWards([]);
      return;
    }

    fetchWards(formData.province_code)
      .then((wards) => {
        setCustomerWards(wards);
        setFormData((current) =>
          current.ward_code && !wards.some((ward) => ward.code === current.ward_code)
            ? { ...current, ward_code: "" }
            : current
        );
      })
      .catch((error) => setLocationError(error instanceof Error ? error.message : "Không thể tải phường/xã."));
  }, [formData.province_code]);

  useEffect(() => {
    if (!recipientData.province_code) {
      setRecipientWards([]);
      return;
    }

    fetchWards(recipientData.province_code)
      .then((wards) => {
        setRecipientWards(wards);
        setRecipientData((current) =>
          current.ward_code && !wards.some((ward) => ward.code === current.ward_code)
            ? { ...current, ward_code: "" }
            : current
        );
      })
      .catch((error) => setLocationError(error instanceof Error ? error.message : "Không thể tải phường/xã."));
  }, [recipientData.province_code]);

  useEffect(() => {
    setIsCartReady(true);
  }, []);

  // If cart is empty and not success, redirect back to cart after hydration.
  useEffect(() => {
    if (isCartReady && cart.length === 0 && !isSuccess) {
      router.push("/cart");
    }
  }, [cart, isCartReady, isSuccess, router]);

  const subtotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const shipping = subtotal > 500000 ? 0 : 30000;
  const tax = subtotal * 0.08;
  const discount = user ? subtotal * 0.05 : 0; // 5% discount for members
  const total = subtotal + shipping + tax - discount;

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleRecipientChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setRecipientData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitError("");
    if (!paymentMethod) {
      setIsPaymentModalOpen(true);
      return;
    }

    const customerProvince = findProvince(provinces, formData.province_code);
    const customerWard = findWard(customerWards, formData.ward_code);

    if (!customerProvince || !customerWard) {
      setSubmitError("Vui lòng chọn đầy đủ tỉnh/thành và phường/xã giao hàng.");
      return;
    }

    const recipientProvince = isDifferentRecipient ? findProvince(provinces, recipientData.province_code) : null;
    const recipientWard = isDifferentRecipient ? findWard(recipientWards, recipientData.ward_code) : null;

    if (isDifferentRecipient && (!recipientProvince || !recipientWard)) {
      setSubmitError("Vui lòng chọn đầy đủ tỉnh/thành và phường/xã của người nhận.");
      return;
    }

    setIsSubmitting(true);

    try {
      const customerAddress = buildFullAddress(formData.address, customerWard, customerProvince);
      const recipientAddress =
        isDifferentRecipient && recipientProvince && recipientWard
          ? buildFullAddress(recipientData.address, recipientWard, recipientProvince)
          : "";

      const response = await fetch("/api/orders", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({
          customer: {
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            address: customerAddress,
            address_detail: formData.address,
            province_code: customerProvince.code,
            ward_code: customerWard.code,
          },
          recipient: isDifferentRecipient
            ? {
                name: recipientData.name,
                phone: recipientData.phone,
                address: recipientAddress,
                address_detail: recipientData.address,
                province_code: recipientProvince?.code,
                ward_code: recipientWard?.code,
              }
            : undefined,
          items: cart.map((item) => ({
            id: item.id,
            quantity: item.quantity,
          })),
          payment_method: paymentMethod,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setSubmitError(data.message || "Kh?ng th? t?o ??n h?ng. Vui l?ng th? l?i.");
        return;
      }

      if (paymentMethod === "vnpay") {
        if (!data.payment_url) {
          setSubmitError("Chưa tạo được liên kết thanh toán VNPay. Vui lòng thử lại.");
          return;
        }

        localStorage.setItem("vanhperfume_pending_vnpay_order", data.order_number || "");
        window.location.href = data.payment_url;
        return;
      }

      setOrderNumber(data.order_number || "");
      setIsSuccess(true);
      clearCart();

      setTimeout(() => {
        router.push("/");
      }, 4000);
    } catch {
      setSubmitError("Kh?ng k?t n?i ???c t?i m?y ch?. Vui l?ng th? l?i.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isSuccess) {
    return (
      <div className="container mx-auto px-4 py-24 min-h-[calc(100vh-160px)] flex items-center justify-center">
        <Card className="max-w-md w-full text-center p-8 border-[#d6bd7a]/25 shadow-[0_24px_80px_rgba(0,0,0,0.36)] bg-gradient-to-b from-background to-primary/5 animate-in fade-in zoom-in duration-500">
          <div className="w-20 h-20 bg-green-100 text-green-600 rounded-none flex items-center justify-center mx-auto mb-6">
            <Check className="w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-[#f7efe1] mb-4">Đặt hàng thành công!</h2>
          <p className="text-[#cfc4ad]/75 mb-8">
            Cảm ơn bạn đã mua sắm tại VANHPERFUME. Đơn hàng của bạn đang được xử lý và sẽ sớm được giao. Hệ thống sẽ tự động quay về trang chủ.
          </p>
          {orderNumber && (
            <p className="mb-6 rounded-none border border-[#d6bd7a]/25 bg-[#d6bd7a]/10 px-4 py-3 text-sm font-semibold text-[#d6bd7a]">
              Mã đơn hàng: {orderNumber}
            </p>
          )}
          {paymentMethod && paymentMethod === "momo" && (
            <p className="mb-6 rounded-none border border-blue-200 bg-blue-50 px-4 py-3 text-sm font-medium text-blue-700">
              Phương thức đã chọn: MoMo. Đây là luồng demo, đơn hàng đã được lưu để xử lý thanh toán.
            </p>
          )}
          <Button asChild className="w-full">
            <Link href="/">Tiếp tục mua sắm ngay</Link>
          </Button>
        </Card>
      </div>
    );
  }

  if (!isCartReady || cart.length === 0) return null; // Avoid flashing empty cart before redirect

  return (
    <>
    {isPaymentModalOpen && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4 py-6 backdrop-blur-sm">
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="payment-required-title"
          className="w-full max-w-md rounded-none border border-[#d6bd7a]/20 bg-[#0d0b0a] p-6 shadow-[0_24px_80px_rgba(0,0,0,0.36)]"
        >
          <div className="flex items-start justify-between gap-4">
            <div className="flex gap-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-none border border-red-100 bg-red-50 text-red-600">
                <AlertCircle className="h-5 w-5" />
              </span>
              <div>
                <h2 id="payment-required-title" className="text-lg font-semibold text-[#f7efe1]">
                  Chưa chọn phương thức thanh toán
                </h2>
                <p className="mt-2 text-sm leading-relaxed text-[#cfc4ad]/75">
                  Vui lòng chọn COD, MoMo hoặc VNPay ngay dưới tổng tiền trước khi xác nhận đơn hàng.
                </p>
              </div>
            </div>
            <button
              type="button"
              onClick={() => setIsPaymentModalOpen(false)}
              className="rounded-none p-1 text-[#cfc4ad]/75 transition-colors hover:bg-[#15110f] hover:text-[#f7efe1] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d6bd7a]/40"
              aria-label="Đóng thông báo"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          <div className="mt-6 flex justify-end gap-3">
            <Button type="button" onClick={() => setIsPaymentModalOpen(false)} className="rounded-none border border-[#d6bd7a]/40 bg-transparent text-[#d6bd7a] hover:bg-[#d6bd7a]/10">
              Đóng
            </Button>
            <Button type="button" onClick={() => setIsPaymentModalOpen(false)} className="rounded-none border border-[#d6bd7a] bg-[#d6bd7a] text-black hover:bg-[#f4df9b]">
              Chọn phương thức
            </Button>
          </div>
        </div>
      </div>
    )}

    <div className="min-h-screen bg-[#070607] px-5 pb-24 pt-12 text-[#f7efe1] sm:px-8 lg:px-14">
      <div className="mb-8">
        <Button variant="ghost" asChild className="rounded-none px-0 text-xs font-semibold uppercase tracking-[0.2em] text-[#d6bd7a] hover:bg-transparent hover:text-[#f4df9b]">
          <Link href="/cart" className="flex items-center gap-2">
            <ArrowLeft className="w-4 h-4" /> Quay lại giỏ hàng
          </Link>
        </Button>
        <h1 className="mt-4 font-serif text-5xl font-light text-[#f7efe1]">Thanh Toán</h1>
      </div>

      <div className="mx-auto grid max-w-[1500px] gap-8 lg:grid-cols-[1fr_460px]">
        {/* Cột trái: Form */}
        <div className="w-full">
          <Card className="border border-[#d6bd7a]/25 bg-[#0d0b0a] text-[#f7efe1] shadow-[0_24px_80px_rgba(0,0,0,0.26)]">
            <CardHeader>
              <CardTitle className="text-xl">Thông tin giao hàng</CardTitle>
            </CardHeader>
            <CardContent>
              {!user && (
                <div className="bg-black/25 p-4 rounded-none mb-6 flex justify-between items-center border border-[#d6bd7a]/20">
                  <div>
                    <p className="font-medium text-[#f7efe1]">Bạn đã có tài khoản?</p>
                    <p className="text-sm text-[#cfc4ad]/75">Đăng nhập để nhận ưu đãi giảm 5%</p>
                  </div>
                  <Button asChild size="sm" className="rounded-none border border-[#d6bd7a]/60 bg-transparent text-xs font-bold uppercase tracking-[0.16em] text-[#d6bd7a] hover:bg-[#d6bd7a] hover:text-black">
                    <Link href="/login">Đăng nhập ngay</Link>
                  </Button>
                </div>
              )}

              <form id="checkout-form" onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-[#f7efe1]">Họ và Tên</label>
                    <Input required className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45" name="name" value={formData.name} onChange={handleInputChange} placeholder="Nguyễn Văn A" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-[#f7efe1]">Số điện thoại</label>
                    <Input required className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45" name="phone" value={formData.phone} onChange={handleInputChange} placeholder="0901234567" />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-medium text-[#f7efe1]">Email</label>
                  <Input required className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45" type="email" name="email" value={formData.email} onChange={handleInputChange} placeholder="nguyenvana@example.com" />
                </div>

                {!isDifferentRecipient && (
                  <div className="space-y-2 animate-in fade-in duration-200">
                    <CheckoutAddressBlock
                      address={formData.address}
                      provinceCode={formData.province_code}
                      wardCode={formData.ward_code}
                      provinces={provinces}
                      wards={customerWards}
                      required={!isDifferentRecipient}
                      detailLabel="Địa chỉ cá nhân"
                      onAddressChange={(value) => setFormData((current) => ({ ...current, address: value }))}
                      onProvinceChange={(value) => setFormData((current) => ({ ...current, province_code: value, ward_code: "" }))}
                      onWardChange={(value) => setFormData((current) => ({ ...current, ward_code: value }))}
                    />
                  </div>
                )}

                <div className="pt-4 border-t border-[#d6bd7a]/20 mt-6">
                  <label className="flex items-center gap-2 cursor-pointer font-medium text-[#f7efe1] mb-4">
                    <input
                      type="checkbox"
                      className="w-4 h-4 rounded border-gray-300 text-[#d6bd7a] focus:ring-primary"
                      checked={isDifferentRecipient}
                      onChange={(e) => setIsDifferentRecipient(e.target.checked)}
                    />
                    Giao hàng cho người nhận khác
                  </label>

                  {isDifferentRecipient && (
                    <div className="space-y-4 bg-black/20 p-4 rounded-none animate-in slide-in-from-top-2 duration-200">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <label className="text-sm font-medium text-[#f7efe1]">Tên người nhận</label>
                          <Input required={isDifferentRecipient} className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45" name="name" value={recipientData.name} onChange={handleRecipientChange} placeholder="Tên người nhận" />
                        </div>
                        <div className="space-y-2">
                          <label className="text-sm font-medium text-[#f7efe1]">SĐT người nhận</label>
                          <Input required={isDifferentRecipient} className="rounded-none border-[#d6bd7a]/25 bg-black/25 text-[#f7efe1] placeholder:text-[#cfc4ad]/45" name="phone" value={recipientData.phone} onChange={handleRecipientChange} placeholder="Số điện thoại" />
                        </div>
                      </div>
                      <div className="space-y-2">
                        <CheckoutAddressBlock
                          address={recipientData.address}
                          provinceCode={recipientData.province_code}
                          wardCode={recipientData.ward_code}
                          provinces={provinces}
                          wards={recipientWards}
                          required={isDifferentRecipient}
                          detailLabel="Địa chỉ giao hàng"
                          onAddressChange={(value) => setRecipientData((current) => ({ ...current, address: value }))}
                          onProvinceChange={(value) => setRecipientData((current) => ({ ...current, province_code: value, ward_code: "" }))}
                          onWardChange={(value) => setRecipientData((current) => ({ ...current, ward_code: value }))}
                        />
                      </div>
                    </div>
                  )}
                </div>
              </form>
              {locationError && (
                <p className="mt-4 rounded-none border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-medium text-amber-700">
                  {locationError}
                </p>
              )}
              {submitError && (
                <p className="mt-4 rounded-none border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
                  {submitError}
                </p>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Cột phải: Tổng kết đơn hàng */}
        <div className="h-12 w-full rounded-none border border-[#d6bd7a] bg-[#d6bd7a] text-xs font-bold uppercase tracking-[0.2em] text-black shadow-none hover:bg-[#f4df9b]">
          <Card className="border border-[#d6bd7a]/25 bg-[#0d0b0a] shadow-[0_24px_80px_rgba(0,0,0,0.26)]">
            <CardHeader>
              <CardTitle className="font-serif text-2xl font-light flex items-center gap-2">
                <ShoppingBag className="w-5 h-5" /> Tóm tắt đơn hàng
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Danh sách SP */}
              <div className="max-h-60 overflow-y-auto space-y-4 pr-2 scrollbar-thin">
                {cart.map(item => (
                  <div key={item.id} className="flex items-center gap-4">
                    <div className="relative w-16 h-16 rounded-none overflow-hidden bg-[#15110f] flex-shrink-0 border border-[#d6bd7a]/20">
                      <Image src={productImageUrl(item.image)} alt={item.name} fill className="object-cover" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium text-[#f7efe1] truncate">{item.name}</h4>
                      <p className="text-xs text-[#cfc4ad]/75">SL: {item.quantity}</p>
                    </div>
                    <div className="font-medium text-sm text-[#f7efe1]">
                      {formatVND(item.price * item.quantity)}
                    </div>
                  </div>
                ))}
              </div>

              <div className="space-y-3 pt-4 border-t border-[#d6bd7a]/20">
                <div className="flex justify-between text-sm">
                  <span className="text-[#cfc4ad]/75">Tạm tính</span>
                  <span className="font-medium text-[#f7efe1]">{formatVND(subtotal)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[#cfc4ad]/75">Phí vận chuyển</span>
                  <span className="font-medium text-[#f7efe1]">{shipping === 0 ? "Miễn phí" : formatVND(shipping)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[#cfc4ad]/75">Thuế (8%)</span>
                  <span className="font-medium text-[#f7efe1]">{formatVND(tax)}</span>
                </div>

                {user && (
                  <div className="flex justify-between text-sm font-medium text-green-700 bg-green-100 p-3 rounded-none border border-green-200 shadow-sm animate-in fade-in slide-in-from-left-2 duration-300">
                    <span className="flex items-center gap-1.5"><Check className="w-4 h-4" /> Ưu đãi thành viên (Giảm 5%)</span>
                    <span>-{formatVND(discount)}</span>
                  </div>
                )}

                <div className="flex justify-between pt-4 border-t border-[#d6bd7a]/20 items-center">
                  <span className="text-lg font-bold text-[#f7efe1]">Tổng cộng</span>
                  <span className="text-2xl font-bold text-[#d6bd7a]">{formatVND(total)}</span>
                </div>
              </div>

              <div className="space-y-3 pt-4 border-t border-[#d6bd7a]/20">
                <div>
                  <h3 className="text-sm font-semibold text-[#f7efe1]">
                    Phương thức thanh toán
                  </h3>
                  <p className="mt-1 text-xs text-[#cfc4ad]/75">
                    Chọn một phương thức trước khi xác nhận đơn hàng.
                  </p>
                </div>

                <div className="grid gap-2">
                  {paymentOptions.map((option) => {
                    const Icon = option.icon;
                    const isSelected = paymentMethod === option.id;

                    return (
                      <button
                        key={option.id}
                        type="button"
                        onClick={() => {
                          setPaymentMethod(option.id);
                          setIsPaymentModalOpen(false);
                        }}
                        className={`flex w-full items-start gap-3 rounded-none border p-3 text-left transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#d6bd7a]/40 ${
                          isSelected
                            ? "border-[#d6bd7a] bg-[#d6bd7a]/5 shadow-sm"
                            : "border-[#d6bd7a]/20 bg-[#0d0b0a] hover:border-primary/40 hover:bg-black/20"
                        }`}
                      >
                        <span
                          className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-none border ${
                            isSelected
                              ? "border-[#d6bd7a] bg-[#d6bd7a] text-black"
                              : "border-[#d6bd7a]/20 bg-[#15110f] text-[#cfc4ad]/75"
                          }`}
                        >
                          <Icon className="h-4 w-4" />
                        </span>

                        <span className="min-w-0 flex-1">
                          <span className="flex items-center justify-between gap-3">
                            <span className="text-sm font-semibold text-[#f7efe1]">
                              {option.title}
                            </span>
                            <span
                              className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-none border ${
                                isSelected
                                  ? "border-[#d6bd7a] bg-[#d6bd7a]"
                                  : "border-muted-foreground/40"
                              }`}
                            >
                              {isSelected && <Check className="h-3.5 w-3.5 text-[#d6bd7a]-foreground" />}
                            </span>
                          </span>
                          <span className="mt-1 block text-xs leading-relaxed text-[#cfc4ad]/75">
                            {option.description}
                          </span>
                        </span>
                      </button>
                    );
                  })}
                </div>
              </div>

              <Button
                type="submit"
                form="checkout-form"
                disabled={isSubmitting}
                className="h-14 w-full rounded-none border border-[#d6bd7a] bg-[#d6bd7a] text-xs font-bold uppercase tracking-[0.22em] text-black shadow-none hover:bg-[#f4df9b]"
              >
                {isSubmitting ? (
                  <div className="flex items-center gap-2">
                    <div className="w-5 h-5 border-2 border-current border-t-transparent rounded-none animate-spin" />
                    {paymentMethod === "vnpay" ? "Đang chuyển sang VNPay..." : "Đang xử lý thanh toán..."}
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <CreditCard className="w-5 h-5" /> {paymentMethod === "vnpay" ? "Thanh toán qua VNPay" : "Xác nhận đặt hàng"}
                  </div>
                )}
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
    </>
  );
}

